"""Small deterministic helpers for a book club reading plan.

Original implementation. SPDX-License-Identifier: CC0-1.0
"""


def _plain_count(value, minimum):
    return type(value) is int and minimum <= value <= 1000000


def _counts(values, minimum):
    if type(values) is not list or any(
        not _plain_count(value, minimum) for value in values
    ):
        raise ValueError("invalid counts")


def page_runs(pages):
    """Represent recorded page numbers as inclusive contiguous runs."""
    _counts(pages, 1)
    ordered = sorted(set(pages))
    if not ordered:
        return []
    result = []
    start = end = ordered[0]
    for page in ordered[1:]:
        if page == end + 1:
            end = page
        else:
            result.append([start, end])
            start = end = page
    result.append([start, end])
    return result



def chapter_sessions(chapter_lengths, limit):
    """Pack whole chapters into consecutive reading sessions."""
    _counts(chapter_lengths, 1)
    if not _plain_count(limit, 1):
        raise ValueError("invalid session limit")
    result = []
    active = []
    total = 0
    for chapter in chapter_lengths:
        if active and total + chapter >= limit:
            result.append(active)
            active = []
            total = 0
        active.append(chapter)
        total += chapter
    if active:
        result.append(active)
    return result



def locate_page(chapter_lengths, page):
    """Find the one-based chapter and chapter page for a book page."""
    _counts(chapter_lengths, 0)
    if not _plain_count(page, 1):
        raise ValueError("invalid book page")
    remaining = page
    for chapter, length in enumerate(chapter_lengths, 1):
        if remaining <= length:
            return {"chapter": chapter, "page": remaining}
        remaining -= length
    return None



def reading_totals(records):
    """Aggregate session page counts by the exact book title."""
    if type(records) is not list:
        raise ValueError("invalid records")
    for record in records:
        if (
            type(record) is not dict
            or set(record) != {"book", "pages"}
            or type(record["book"]) is not str
            or not _plain_count(record["pages"], 0)
        ):
            raise ValueError("invalid reading record")
    totals = {}
    for record in records:
        book = record["book"]
        totals[book] = totals.get(book, 0) + record["pages"]
    return [{"book": book, "pages": pages} for book, pages in totals.items()]



def reading_percentage(completed, total):
    """Report whole percent progress, capped at one hundred."""
    if not _plain_count(completed, 0) or not _plain_count(total, 1):
        raise ValueError("invalid progress counts")
    return min(100, (200 * completed + total) // (2 * total))
